E_M[S_I(\bar{Y})] &= E_M\left[(\bar{Y}_I \mid p = I) - (\bar{Y}_T \mid p = I)\right] \\
&= \frac{1}{N_I}\sum_{j \in U_I}(\mu_j + B_{Ij}) - \frac{1}{N_T}\sum_{j \in U_T}(\mu_j + B_{Ij}) \\
&= \bar{\mu}_I + \bar{B}_I(I) - \bar{\mu}_T - \bar{B}_T(I) \\
&= [\bar{\mu}_I - \bar{\mu}_T] + [\bar{B}_I(I) - \bar{B}_T(I)]
\end{aligned}
\tag{2.18}

\begin{aligned}
E_M[M_T(\bar{Y})] &= E_M\left[(\bar{Y}_T \mid p = T) - (\bar{Y}_T \mid p = I)\right] \\
&= \frac{1}{N_T} \sum_{j \in U_T} (\mu_j + B_{Tj}) - \frac{1}{N_T} \sum_{j \in U_T} (\mu_j + B_{Ij}) \\
&= \frac{1}{N_T} \sum_{j \in U_T} (B_{Tj} - B_{Ij}) \\
&= \bar{B}_T(T) - \bar{B}_T(I)
\end{aligned} \tag{2.20}

\begin{aligned}
E_M[M_I(\bar{Y})] &= E_M\left[(\bar{Y}_I \mid p = I) - (\bar{Y}_I \mid p = T)\right] \\
&= \frac{1}{N_I} \sum_{j \in U_I} (\mu_j + B_{Ij}) - \frac{1}{N_I} \sum_{j \in U_I} (\mu_j + B_{Tj}) \\
&= \frac{1}{N_I} \sum_{j \in U_I} (B_{Ij} - B_{Tj}) \\
&= \bar{B}_I(I) - \bar{B}_I(T)
\end{aligned} \tag{2.22}

